@font-face {
  font-family: "Comic Shanns Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Comic Shanns Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "D2Coding";
  src: url("data:font/woff2;base64,") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "D2Coding";
  src: url("data:font/woff2;base64,") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

body {
  --font-text-theme: "Comic Shanns Mono", "D2Coding", sans-serif;
  --font-monospace-theme: "Comic Shanns Mono", "D2Coding", monospace;
  --font-interface-theme: "Comic Shanns Mono", "D2Coding", sans-serif;
}
